    this.lo.push(n);                // everyone enters through lo
    this.hi.push(this.lo.pop());    // lo's top crosses the seam
    if (this.hi.size > this.lo.size) {
      this.lo.push(this.hi.pop());  // hi outgrew lo — hand one back
    }
