lru.put(1, 10);   // a fresh card onto an empty shelf
lru.put(2, 20);   // another one
lru.get(1);       // HIT — touching 1 makes it the freshest
lru.put(3, 30);   // the shelf is full now

lru.get(4);       // never seen -> -1
lru.put(2, 25);   // UPDATE — a new value counts as a touch
lru.put(5, 50);   // full: the front card falls off

lru.get(1);       // 1 already fell off -> -1
lru.get(3);       // still here -> 30
