  // The Set answers "is this number here?" instantly,
  // and drops duplicates on the way in.
  const set = new Set(nums);
  let best = 0;

  for (const num of set) {
    // The filter that makes this O(n): only a run's TRUE
    // first number is allowed to count upward, so no run
    // is ever re-counted from somewhere in its middle.
    const startsARun = !set.has(num - 1);

    if (startsARun) {
      let streak = 1;
      while (set.has(num + streak)) {
        streak += 1;
      }

      if (streak > best) {
        best = streak;
      }
    }
  }

  return best;
