  // Base cases, both reporting whatever we are standing
  // on: an empty spot found nothing, and a node that IS
  // one of the targets found itself. A target counts as
  // its own ancestor, so it never looks any deeper.
  if (node === null || node === p || node === q) {
    return node;          // whatever I am standing on
  }

  const foundLeft = lowestCommonAncestor(node.left, p, q);
  const foundRight = lowestCommonAncestor(node.right, p, q);

  const bothSidesReported = foundLeft !== null && foundRight !== null;
  if (bothSidesReported) {
    return node;          // the split point IS the answer
  }

  // At most one side found anything: pass it straight up
  // unchanged. Once a split point is reported, every node
  // above sees only this one side and relays it to the top.
  return foundLeft ?? foundRight;
