// every reference kept is a subtree React.memo gets to skip`,ng=`// Rebuild only the path root → target; untouched branches keep their reference.
export function insertNode(nodes, folderId, child) {
  let changed = false;                   // did anything below move?
  const next = nodes.map((node) => {
    if (node.id === folderId && node.kind === 'folder') {
      changed = true;
      const children = [...(node.children ?? []), child].sort(compareNodes);
      return { ...node, children };      // a NEW folder object
    }
    if (node.children) {                 // a folder — descend
      const children = insertNode(node.children, folderId, child);
      if (children !== node.children) {  // something below changed
        changed = true;
        return { ...node, children };    // rebuild this ancestor
      }
    }
    return node;                         // untouched → same reference
  });
  return changed ? next : nodes;         // no-op ⇒ the SAME array back
}

export function removeNode(nodes, id) {
  let changed = false;                   // same flag, same contract
  const out = [];
  for (const node of nodes) {
    if (node.id === id) {
      changed = true;
      continue;                          // drop it, and its whole subtree
    }
    if (node.children) {                 // descend into the folder
      const children = removeNode(node.children, id);
      if (children !== node.children) {
        changed = true;
        out.push({ ...node, children }); // rebuild the ancestor on the way out
        continue;
      }
    }
    out.push(node);                      // kept as-is → same reference
  }
  return changed ? out : nodes;          // still the SAME array on a no-op
}

